"""Six original grade-one reading sequences; rules are local fictional instructions."""
def author(E,C,O):
 S='plan-G1-information-07'
 E(S,'S1','A','먼저 하는 일과 나중에 하는 일',
 '종이 고리를 만들어요. 먼저 종이를 길게 잘라요. 다음에 종이의 두 끝을 붙여요.\n먼저와 다음에는 일의 차례를 알려 주는 말이에요. 끝을 붙이기 전에 종이를 잘라야 해요.',
 '차례말과 행동을 함께 읽는다. 가위 사용은 성인 지도를 전제로 하며 이 자료는 실제 만들기 실습을 요구하지 않는다.',[
 C('먼저 하는 일은 무엇인가요?','종이를 길게 잘라요.','먼저 뒤에 나오는 행동은 자르기다.',[('종이의 끝을 붙여요.','다음에 하는 일을 먼저로 바꿨다.'),('종이에 이름을 써요.','자료에 없는 행동을 더했다.')],'먼저 종이를 길게'),
 O('ordering','자르기와 붙이기를 차례대로 쓰세요.','자르기 → 붙이기','붙이기 전에 종이를 잘라야','두 행동은 쓰지만 차례 표시가 없음','붙이기 → 자르기로 씀'),
 O('evidence_selection','두 끝을 붙일 때를 알려 주는 말을 찾으세요.','다음에','다음에 종이의 두 끝','끝을 붙여요만 씀','먼저를 고름')])
 E(S,'S2','A','찰흙 이름표',
 '찰흙을 둥글게 뭉쳐요. 그다음 손바닥으로 납작하게 눌러요. 나무 막대로 이름을 새겨요.\n마지막으로 완성한 이름표를 받침에 올려요. 이 글에서는 받침에 올린 뒤 이름을 새기지 않아요.',
 '차례말이 없는 첫 행동도 확인한다. 순서 확인을 찰흙의 성질을 아는 문제로 바꾸지 않는다.',[
 C('납작하게 누른 다음에 하는 일은 무엇인가요?','이름을 새겨요.','납작하게 누르기 뒤에 이름을 새기고, 받침에 올리기는 그 뒤다.',[('둥글게 뭉쳐요.','이미 누르기 전에 한 일이다.'),('다시 둥글게 뭉쳐요.','되돌아가는 행동은 제시되지 않았다.')],'나무 막대로 이름을'),
 O('ordering','뭉치기, 이름 새기기, 납작하게 누르기를 차례대로 쓰세요.','뭉치기 → 누르기 → 이름 새기기',['찰흙을 둥글게','손바닥으로 납작하게','나무 막대로 이름을'],'처음과 끝은 맞지만 가운데를 빠뜨림','이름부터 새긴다고 씀'),
 O('evidence_selection','받침에 올리는 일이 가장 나중임을 알려 주는 차례말을 찾으세요.','마지막으로','마지막으로 완성한 이름표를','받침에 올려요만 써 차례말이 없음','그다음을 고름'),
 O('revision','받침에 올린 뒤 이름을 새겨요를 글의 차례에 맞게 고치세요.','이름을 새긴 뒤 받침에 올려요.','완성한 이름표를 받침에','받침에 올려요만 씀','고칠 필요 없다고 함')])
 E(S,'S3','A','주머니에 넣을 쪽지',
 '접기 전 쪽지에 그림을 그려요. 그림을 다 그리면 쪽지를 반으로 접어요.\n접은 쪽지를 작은 주머니에 넣어요. 주머니를 닫은 다음 끈으로 묶어요.',
 '두 문단의 행동을 이어 읽는다. 문단이 바뀌었다고 다른 만들기 과정으로 나누지 않는다.',[
 C('주머니에 넣기 바로 전에 하는 일은 무엇인가요?','쪽지를 반으로 접어요.','접은 쪽지를 넣는다고 했으므로 접기가 바로 앞선다.',[('주머니를 끈으로 묶어요.','묶기는 넣고 닫은 뒤다.'),('쪽지에 그림을 그려요.','그리기는 접기보다 앞선 일이다.')],'접은 쪽지를 작은'),
 O('ordering','그리기, 접기, 넣기, 닫기, 묶기를 차례대로 쓰세요.','그리기 → 접기 → 넣기 → 닫기 → 묶기',['그림을 다 그리면','주머니를 닫은 다음'],'한 행동만 빠뜨리고 나머지 순서는 맞음','묶은 다음 넣는다고 씀'),
 O('explanation','그림을 그린 다음 바로 주머니에 넣으면 빠지는 일은 무엇인가요?','쪽지를 반으로 접는 일이 빠진다.','쪽지를 반으로 접어요.','접는다고만 써 대상이 모호함','그림을 지워야 한다고 함'),
 O('evidence_selection','끈으로 묶기 전에 주머니를 닫는다는 부분을 찾으세요.','주머니를 닫은 다음 끈으로 묶어요.','주머니를 닫은 다음','끈으로 묶어요만 써 앞선 행동이 없음','접은 쪽지를 고름')])
 E(S,'S4','A','비어 있는 차례 칸',
 '종이배를 작은 접시에 올려요. 접시 위의 배에 깃발을 꽂아요. 깃발을 꽂은 배를 전시대에 옮겨요.\n준이의 차례 카드예요. 접시에 올리기 → 빈칸 → 전시대에 옮기기. 준이는 카드의 빈칸을 채우려 해요.',
 '빈칸 뒤의 깃발을 꽂은 배라는 상태를 앞 문장과 연결하게 한다. 응답 전에 해당 문장을 대신 읽거나 지목했다면 지원을 기록한다.',[
 C('빈칸에 들어갈 일은 무엇인가요?','배에 깃발 꽂기','옮길 때 배는 이미 깃발을 꽂은 상태이므로 가운데 행동이 필요하다.',[('배에서 깃발 빼기','옮기는 배에 깃발이 꽂혀 있다는 상태와 맞지 않는다.'),('전시대에서 배 내리기','전시대로 옮기기 전의 행동이 아니다.')],'깃발을 꽂은 배를'),
 O('explanation','전시대로 옮길 때 배에 무엇이 있어야 하나요? 앞 문장의 행동도 쓰세요.','깃발이 있어야 한다. 접시 위의 배에 깃발을 꽂았다.',['배에 깃발을 꽂아요.','깃발을 꽂은 배를'],'깃발만 쓰고 앞 행동을 연결하지 못함','아무것도 없어야 한다고 씀'),
 O('revision','접시에 올리기 → 전시대에 옮기기만 적은 카드에 빠진 일을 넣으세요.','접시에 올리기 → 깃발 꽂기 → 전시대에 옮기기','접시 위의 배에 깃발을','세 행동을 적었지만 접시와 전시대 순서가 불명확함','깃발을 전시 후에 꽂도록 고침'),
 O('question_generation','글의 어느 부분을 보면 빈칸을 알 수 있을지 묻는 질문을 만드세요.','전시대로 옮긴 배는 그전에 어떤 일을 마친 배인가요?','깃발을 꽂은 배를','깃발은 어디 있나요처럼 관련 대상만 물음','종이배 색이 무엇인지 물음')])
 E(S,'S5','A','붙인 뒤에 이름을 쓸까',
 '이번 책갈피는 먼저 종이에 그림을 그려요. 그림을 그린 다음 그림 아래에 이름을 쓰고, 이름 위에 투명 테이프를 붙여요.\n서우의 카드에는 그림 그리기 → 테이프 붙이기 → 이름 쓰기라고 적혀 있어요. 서우는 이름만 들어가면 차례는 같다고 말해요. 지후는 이름을 쓰는 때를 다시 읽어 보자고 말해요.',
 '다른 의견을 제시하되 본문이 오류의 정답을 미리 설명하지 않게 한다. 테이프의 일반 성질 대신 이 자료의 지정 순서로 판단한다.',[
 C('글에 맞게 고친 차례는 어느 것인가요?','그리기 → 이름 쓰기 → 테이프 붙이기','그림을 그린 다음 이름을 쓰고 이름 위에 테이프를 붙이므로 두 앞뒤 관계를 모두 지킨다.',[('이름 쓰기 → 그리기 → 테이프 붙이기','그림을 그린 다음 이름을 쓴다는 시간 순서를 바꿨다.'),('그리기 → 테이프 붙이기 → 이름 쓰기','서우 카드의 순서 문제를 그대로 둔다.')],'그림을 그린 다음 그림 아래에 이름을 쓰고'),
 O('classification','서우 카드에서 그대로 둘 일 / 자리를 바꿀 일을 나누세요.','그대로:맨 앞 그림 그리기 / 바꾸기:이름 쓰기와 테이프 붙이기의 차례','이름 위에 투명 테이프를','옮길 두 행동 중 하나만 씀','그림 그리기를 맨 뒤로 옮김'),
 O('explanation','이름만 있으면 차례가 같다는 서우의 말에 답하세요.','같은 일이 모두 있어도 이름을 먼저 쓰고 테이프를 나중에 붙여야 이 글의 차례와 같다.','이름을 쓰고, 이름 위에','차례가 다르다고만 씀','들어간 일이 같으면 어떤 순서도 된다고 함'),
 O('evidence_selection','이름 쓰기와 테이프 붙이기의 앞뒤를 알 수 있는 부분을 찾으세요.','이름을 쓰고, 이름 위에 투명 테이프를 붙여요.','이름을 쓰고, 이름 위에','이름 위에만 적어 두 행동 연결이 없음','서우의 잘못된 카드만 근거로 듦'),
 O('revision','서우 카드의 뒤 두 칸을 고쳐 쓰세요.','이름 쓰기 → 테이프 붙이기','이름을 쓰고, 이름 위에','이름 쓰기만 적음','테이프 붙이기를 먼저 유지함')])
 E(S,'S6','A','두 가지 장식의 차례',
 '자료 가. 문고리 장식은 종이에 그림을 그리고, 종이에 고리를 붙여요. 고리를 붙인 뒤 문손잡이에 걸어요.\n자료 나. 책상 장식은 종이를 접어 세워요. 세운 종이 앞에 이름표를 붙여요. 이 장식에는 고리를 쓰지 않아요.\n하나는 문에 걸고 하나는 책상에 세우려 해요. 두 안내를 읽고 각각의 차례 카드를 만들어요.',
 '새 두 자료의 과정을 따로 보존하는 전이 초안이다. 책상 장식의 접기를 문 장식에 옮기지 않는지 본다. 실제 만들기는 필수가 아니다.',[
 C('문고리 장식의 차례로 맞는 것은 무엇인가요?','그림 → 고리 붙이기 → 걸기','자료 가는 그림, 고리 부착, 걸기 순서이고 자료 나와 구별된다.',[('접어 세우기 → 고리 붙이기 → 걸기','책상 장식의 첫 행동을 섞었다.'),('그림 → 걸기 → 고리 붙이기','고리를 붙인 뒤 건다는 순서를 바꿨다.')],'고리를 붙인 뒤 문손잡이에'),
 O('ordering','책상 장식의 두 행동을 차례대로 쓰세요.','접어 세우기 → 이름표 붙이기','세운 종이 앞에 이름표','두 행동은 쓰지만 순서를 표시하지 않음','이름표를 붙인 뒤 고리를 단다고 씀'),
 O('classification','고리 붙이기와 이름표 붙이기를 가 / 나로 나누세요.','가:고리 붙이기 / 나:이름표 붙이기',['종이에 고리를 붙여요.','종이 앞에 이름표를'],'한 행동만 맞게 연결함','두 행동을 모두 가에 넣음'),
 O('revision','책상 장식은 고리를 붙여 문에 건다는 말을 고치세요.','책상 장식은 종이를 접어 세우고 이름표를 붙인다.',['종이를 접어 세워요.','이 장식에는 고리를 쓰지'],'고리를 지웠지만 책상 장식의 차례가 없음','책상 장식에도 고리를 남김'),
 O('writing','두 장식의 차례를 각각 한 줄로 적으세요.','문:그림 → 고리 붙이기 → 걸기 / 책상:접어 세우기 → 이름표 붙이기',['고리를 붙인 뒤','세운 종이 앞에'],'한 장식의 순서만 완전하게 씀','서로 다른 두 과정을 하나로 섞음'),
 O('explanation','친구가 고리를 어느 장식에 쓸지 물으면 자료를 보고 답하세요.','문고리 장식에 쓴다. 책상 장식은 고리를 쓰지 않는다고 했다.','이 장식에는 고리를 쓰지','문에 쓴다고만 하고 두 자료를 구별한 근거가 없음','두 장식에 모두 쓴다고 함')])
